import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadBastarData(){const t=readFileSync(resolve(__dirname,"../../bastar-iron-craft-explorer/bastar-data.js"),"utf-8");return new Function(t+"\nreturn { BASTAR_INFO, PROCESS_STEPS, TRADITIONAL_DESIGNS, ARTISAN_SPOTLIGHT, GALLERY_IMAGES, REFERENCES };")()}describe("Bastar Iron Craft Explorer — Data Tests",()=>{let t;beforeAll(()=>{t=loadBastarData()}),describe("BASTAR_INFO metadata",()=>{it("contains correct Bastar Iron Craft metadata and GI tag",()=>{expect(t.BASTAR_INFO.id).toBe("bastar-iron-craft"),expect(t.BASTAR_INFO.title).toContain("Bastar Iron Craft"),expect(t.BASTAR_INFO.originRegion).toContain("Chhattisgarh"),expect(t.BASTAR_INFO.giTagStatus).toContain("GI")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(t.BASTAR_INFO.quickStats)).toBe(!0),expect(t.BASTAR_INFO.quickStats.length).toBe(6)})}),describe("PROCESS_STEPS & TRADITIONAL_DESIGNS",()=>{it("contains manufacturing steps and traditional motifs",()=>{expect(Array.isArray(t.PROCESS_STEPS)).toBe(!0),expect(t.PROCESS_STEPS.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(t.TRADITIONAL_DESIGNS)).toBe(!0),expect(t.TRADITIONAL_DESIGNS.length).toBeGreaterThanOrEqual(4)})}),describe("ARTISAN_SPOTLIGHT",()=>{it("contains artisan community details",()=>{expect(t.ARTISAN_SPOTLIGHT.title).toBeDefined(),expect(t.ARTISAN_SPOTLIGHT.description).toContain("Kondagaon")})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(t.GALLERY_IMAGES)).toBe(!0),expect(t.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(t.REFERENCES)).toBe(!0),expect(t.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});